  "implementation": "def solve(case):
    capacity = case['capacity']
    trials = case['trials']
    failure_by_sig = {}
    successes = []
    for i, t in enumerate(trials):
        entry = {
            'last_trial': i,
            'reflection': t['reflection'],
            'signature': t['signature'],
            'success': t['success']
        }
        if not entry['success']:
            sig = entry['signature']
            if sig not in failure_by_sig or entry['last_trial'] > failure_by_sig[sig]['last_trial']:
                failure_by_sig[sig] = entry
        else:
            successes.append(entry)
    all_entries = list(failure_by_sig.values()) + successes
    all_entries.sort(key=lambda x: (x['success'], -x['last_trial'], x['signature']))
    selected = all_entries[:capacity]
    selected.sort(key=lambda x: x['last_trial'])
    memory = selected
    signatures = [e['signature'] for e in selected]
    return {'memory': memory, 'signatures': signatures}
